#!/usr/bin/env python3
"""Compute ground truth for the Uljin-Samcheok reported wind-dry-burn task."""

from __future__ import annotations

import html
import json
import re
from datetime import date
from pathlib import Path


TASK_ID = "CSX-177_Q1"
EVENT_ID = "CSX-177"
TASK_DIR = Path(__file__).resolve().parent
ROOT = TASK_DIR.parents[2]
PACKAGE = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = TASK_DIR / "computed_gt.json"

ANCHOR_JSON = "data/event_reports/event_reports_003_Locked_event_anchor_2022_Uljin-Samcheok_wildfire_in_South_Korea.json"
REPORT_HTML = "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html"
TARGET_FAMILY = "uljin_samcheok_reported_wind_dry_burn_forcing_index"

SOURCE_FILES = [
    "metadata/event.json",
    ANCHOR_JSON,
    REPORT_HTML,
]


def load_json(relative_path: str) -> dict:
    with (PACKAGE / relative_path).open("r", encoding="utf-8", errors="replace") as handle:
        return json.load(handle)


def read_text(relative_path: str) -> str:
    return (PACKAGE / relative_path).read_text(encoding="utf-8", errors="ignore")


def clean_html_text(raw: str) -> str:
    raw = re.sub(r"<script[\s\S]*?</script>", " ", raw, flags=re.I)
    raw = re.sub(r"<style[\s\S]*?</style>", " ", raw, flags=re.I)
    raw = re.sub(r"<[^>]+>", " ", raw)
    return re.sub(r"\s+", " ", html.unescape(raw)).strip()


def report_text() -> str:
    raw = read_text(REPORT_HTML)
    paragraphs = re.findall(r"<p[^>]*>(.*?)</p>", raw, flags=re.I | re.S)
    return " ".join(clean_html_text(paragraph) for paragraph in paragraphs)


def inclusive_days(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days + 1


def first_int(pattern: str, text: str, label: str) -> int:
    match = re.search(pattern, text, flags=re.I)
    if not match:
        raise ValueError(f"missing {label}")
    return int(match.group(1).replace(",", ""))


def build_ground_truth() -> dict:
    event = load_json("metadata/event.json")
    anchor = load_json(ANCHOR_JSON)
    text = report_text()

    event_start = anchor["temporal_window"]["start_date"]
    event_end = anchor["temporal_window"]["end_date"]
    n_days = inclusive_days(event_start, event_end)

    continued_match = re.search(r"By March ([0-9]+).*?continued to detect fire activity", text, flags=re.I)
    if not continued_match:
        raise ValueError("missing continued fire activity date")
    continued_fire_date = f"2022-03-{int(continued_match.group(1)):02d}"
    early_active_days = inclusive_days(event_start, continued_fire_date)
    early_active_fraction = round(early_active_days / n_days, 3)

    anchors = {
        "strong_winds_text": bool(re.search(r"strong winds", text, flags=re.I)),
        "dry_weather_text": bool(re.search(r"dry weather", text, flags=re.I)),
        "westerly_smoke_transport_text": bool(
            re.search(r"westerly winds sent smoke plumes streaming toward southern Japan", text, flags=re.I)
        ),
    }
    anchor_count = sum(1 for value in anchors.values() if value)

    burned_hectares = first_int(r"charred nearly ([0-9,]+) hectares", text, "burned hectares")
    burned_area_kha = round(burned_hectares / 1000.0, 3)
    homes_destroyed = first_int(r"destroyed more than ([0-9,]+) homes", text, "homes destroyed")
    evacuated_people = first_int(r"forced more than ([0-9,]+) people to evacuate", text, "evacuated people")
    firefighters_mobilized = first_int(r"Around ([0-9,]+) people and dozens of helicopters", text, "firefighters")

    index_value = anchor_count * early_active_fraction * burned_area_kha
    index_rounded = round(index_value, 2)
    severity_class = "high" if index_value >= 20 else "moderate" if index_value >= 10 else "lower"
    interpretation = (
        "The 20.40 reported wind-dry-burn index crosses the high threshold because all three report anchors "
        "are present, early fire activity spans 4 of 10 event days, and the report gives about 17.0 kha burned."
    )

    primary_gt = {
        "reported_wind_dry_burn_forcing_index": index_rounded,
        "units": "thousand-hectare anchor-fraction index",
        "inputs": {
            "A_report_anchor_count": anchor_count,
            "E_early_active_days": early_active_days,
            "N_event_days": n_days,
            "early_active_fraction": early_active_fraction,
            "H_burned_area_kha": burned_area_kha,
            "anchors": anchors,
        },
        "severity_class": severity_class,
        "interpretation": interpretation,
    }

    rubric = [
        {
            "name": "Final numeric index",
            "points": 4,
            "description": "Reports the reported wind-dry-burn forcing index as 20.40 or an equivalent value within +/-0.05.",
            "partial_credit": "Give 2-3 points for a value within +/-1.0 caused by rounding or a small arithmetic error.",
        },
        {
            "name": "Report anchor extraction",
            "points": 4,
            "description": "Finds all three report anchors: strong winds, dry weather, and westerly smoke transport toward southern Japan.",
            "partial_credit": "Give 1 point for each correct anchor and 1 point for correctly counting the anchors.",
        },
        {
            "name": "Early activity window",
            "points": 3,
            "description": "Uses March 4-13 as a 10-day event window and March 4-7 as a 4-day early active fire interval.",
            "partial_credit": "Give 1-2 points if the dates are identified but one inclusive-day calculation is wrong.",
        },
        {
            "name": "Burned-area extraction",
            "points": 3,
            "description": "Extracts nearly 17,000 hectares and converts it to 17.0 thousand hectares for the formula.",
            "partial_credit": "Give 1-2 points if the hectare value is found but conversion or rounding is wrong.",
        },
        {
            "name": "Formula and threshold",
            "points": 3,
            "description": "Applies RWDBFI = A * (E / N) * Hkha and classifies the result as high because it is at least 20.",
            "partial_credit": "Give 1-2 points for using the right variables but misapplying the threshold or fraction.",
        },
        {
            "name": "Bounded interpretation",
            "points": 2,
            "description": "Interprets the score as a report-grounded screening index, not a measured PM2.5 concentration, smoke dose, or health outcome.",
            "partial_credit": "Give 1 point for a mostly bounded interpretation with one minor overstatement.",
        },
        {
            "name": "Requested output format",
            "points": 1,
            "description": "Returns compact JSON with the requested top-level fields.",
            "partial_credit": "Give no credit if the answer is unstructured prose only.",
        },
    ]

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "task_subtype": "reported_wind_dry_burn_forcing_index",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L2",
        "target_family": TARGET_FAMILY,
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": {
                "start_date": event_start,
                "end_date": event_end,
                "inclusive_days": n_days,
            },
            "supporting_context": {
                "continued_fire_activity_date": continued_fire_date,
                "burned_hectares": burned_hectares,
                "homes_destroyed_more_than": homes_destroyed,
                "evacuated_people_more_than": evacuated_people,
                "firefighters_mobilized_about": firefighters_mobilized,
            },
            "thresholds": {
                "high": "RWDBFI >= 20",
                "moderate": "10 <= RWDBFI < 20",
                "lower": "RWDBFI < 10",
            },
        },
        "numeric_tolerances": {
            "reported_wind_dry_burn_forcing_index": 0.05,
            "inputs.E_early_active_days": 0,
            "inputs.N_event_days": 0,
            "inputs.H_burned_area_kha": 0.05,
            "inputs.early_active_fraction": 0.001,
        },
        "judge_anchors": {
            "required_claims": [
                "Uses March 4-13, 2022 as a 10-day inclusive event window.",
                "Uses March 4-7 as the 4-day early active fire interval within the event window.",
                "Counts strong winds, dry weather, and westerly smoke transport as three report anchors.",
                "Uses nearly 17,000 hectares as 17.0 thousand hectares.",
                "Computes 3 * (4 / 10) * 17.0 = 20.40 and classifies it as high.",
            ],
            "forbidden_claims": [
                "Using off-event Open-Meteo or NASA POWER daily weather values as local Uljin-Samcheok measurements.",
                "Treating the index as measured PM2.5 concentration, smoke dose, health outcome, ignition cause, or exact spread path.",
            ],
            "acceptable_variants": [
                "Final answer may be reported as 20.4 or 20.40 if the class and units are clear.",
                "Units may be described as a thousand-hectare report-anchor index or equivalent dimensionless screening units.",
            ],
        },
        "rubric": {"total_points": 20, "criteria": rubric},
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": [
                "Off-event Open-Meteo and NASA POWER weather files are not used in this ground truth.",
                "The score is computed from declared event anchor metadata and NASA Earth Observatory report text.",
            ],
        },
    }


def main() -> None:
    OUT.write_text(json.dumps(build_ground_truth(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
